package cn.gmiya.malodylink;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.*;
final class GameplayView extends View {
 Bitmap background;GameplayChart chart;double time,approach=2;boolean followScroll=false;private final Paint p=new Paint(3);private final Path path=new Path();private final Matrix matrix=new Matrix();private final Map<String,Bitmap> sprites=new HashMap<>();
 GameplayView(Context c){super(c);setContentDescription("AUTO自动游玩预览，不记录成绩");}
 double distance(double at){return followScroll?chart.travel(at)-chart.travel(time):at-time;}
 float y(double at){return getHeight()*.76f-(float)(distance(at)/approach)*getHeight()*.735f;}
 float half(float y){return getWidth()*(.075f+.30f*(y-getHeight()*.025f)/(getHeight()*.735f));}
 float x(double value,float y){return getWidth()/2f+(float)(value/128-1)*half(y);}
 void color(int c){p.setColor(c);p.setStyle(Paint.Style.FILL);}
 void text(Canvas c,String s,float size,float y,int col){color(col);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(size);p.setTextAlign(Paint.Align.CENTER);c.drawText(s,getWidth()/2f,y,p);}
 Bitmap image(String name){if(!sprites.containsKey(name))try(java.io.InputStream in=getContext().getAssets().open("gameplay-skin/"+name+".png")){sprites.put(name,BitmapFactory.decodeStream(in));}catch(Exception ignored){sprites.put(name,null);}return sprites.get(name);}
 void segment(Canvas c,double a,double ax,double b,double bx){if(b<a)return;float ya=y(a),yb=y(b);p.setColor(0xff83ed79);p.setStrokeWidth(Math.max(5,getWidth()*.006f));c.drawLine(x(ax,ya),ya,x(bx,yb),yb,p);}
 void head(Canvas c,GameplayChart.Note n,double at,double pos,boolean hold){float yy=y(at);if(yy<getHeight()*.02||yy>getHeight()*.79)return;float l=x(Math.max(0,pos-n.width/2),yy),r=x(Math.min(256,pos+n.width/2),yy),h=Math.max(4,getHeight()*.022f);Bitmap b=image(chart.keys+(hold?"notel":"note")+Math.max(1,Math.min(chart.keys,(int)(pos*chart.keys/256)+1)));color(hold?0xff87ed76:0xff25d9eb);if(b==null)c.drawRoundRect(l,yy-h,r,yy+h,4,4,p);else{matrix.setPolyToPoly(new float[]{0,0,b.getWidth(),0,b.getWidth(),b.getHeight(),0,b.getHeight()},0,new float[]{l+2,yy-h,r-2,yy-h,r,yy+h,l,yy+h},0,4);c.drawBitmap(b,matrix,p);}}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(0xff06111b);if(background!=null){float scale=Math.max(getWidth()/(float)background.getWidth(),getHeight()/(float)background.getHeight());float w=background.getWidth()*scale,h=background.getHeight()*scale;color(0xffffffff);c.drawBitmap(background,null,new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2),p);color(0x88000000);c.drawRect(0,0,getWidth(),getHeight(),p);}if(chart==null)return;float top=getHeight()*.025f,bottom=getHeight()*.76f;
 for(int lane=0;lane<chart.keys;lane++){double a=lane*256.0/chart.keys,b=(lane+1)*256.0/chart.keys;path.reset();path.moveTo(x(a,top),top);path.lineTo(x(b,top),top);path.lineTo(x(b,bottom),bottom);path.lineTo(x(a,bottom),bottom);path.close();color(lane%2==0?0xea191a1e:0xea11151b);c.drawPath(path,p);p.setColor(0xff4d6b79);p.setStrokeWidth(1);c.drawLine(x(a,top),top,x(a,bottom),bottom,p);}
 // Side rails and the desk use the same perspective as the lane geometry.
 for(int side:new int[]{-1,1}){float tx=getWidth()/2f+side*half(top),bx=getWidth()/2f+side*half(bottom);p.setColor(0xff17191c);p.setStrokeWidth(getWidth()*.024f);c.drawLine(tx,top,bx,bottom,p);p.setColor(0xff827568);p.setStrokeWidth(getWidth()*.010f);c.drawLine(tx,top,bx,bottom,p);p.setColor(0xffc4b098);p.setStrokeWidth(2);c.drawLine(tx-side*4,top,bx-side*4,bottom,p);}
 for(int lane=0;lane<chart.keys;lane++){double a=lane*256.0/chart.keys,b=(lane+1)*256.0/chart.keys;float lower=getHeight()*.87f;path.reset();path.moveTo(x(a,bottom)+3,bottom+8);path.lineTo(x(b,bottom)-3,bottom+8);path.lineTo(x(b,lower)-4,lower);path.lineTo(x(a,lower)+4,lower);path.close();p.setShader(new LinearGradient(0,bottom,0,lower,new int[]{0xff574a42,0xff1d252c,0xff071b25},null,Shader.TileMode.CLAMP));c.drawPath(path,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(0xffa18a71);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff34728b);p.setStrokeWidth(3);c.drawLine(x(a,lower)+4,lower,x(b,lower)-4,lower,p);}
 p.setColor(0xffbea58a);p.setStrokeWidth(4);c.drawLine(x(0,bottom),bottom,x(256,bottom),bottom,p);
 int combo=0;boolean hit=false;boolean[] glow=new boolean[chart.keys];c.save();c.clipRect(0,top,getWidth(),bottom+8);
 for(GameplayChart.Note n:chart.notes){if(n.at<=time)combo++;if(n.end<time-.14||Math.min(distance(n.at),distance(n.end))>approach)continue;if(n.at<=time&&time-n.at<.14){hit=true;glow[Math.min(chart.keys-1,(int)(n.x*chart.keys/256))]=true;}
 if(!n.points.isEmpty()){double prev=n.at,px=n.x,pos=n.x;for(double[] pt:n.points){if(pt[0]>=time&&distance(prev)<=approach){segment(c,Math.max(prev,time),px,pt[0],px);if(distance(pt[0])<=approach)segment(c,pt[0],px,pt[0],pt[1]);}if(pt[0]<=time)pos=pt[1];prev=pt[0];px=pt[1];}head(c,n,Math.max(n.at,time),pos,true);if(n.at<=time&&n.end>=time)glow[Math.min(chart.keys-1,(int)(pos*chart.keys/256))]=true;}
 else if(n.at>=time)head(c,n,n.at,n.x,n.dir!=0);
 int direction=n.points.isEmpty()?n.dir:n.tail;double at=n.points.isEmpty()?n.at:n.end,pos=n.points.isEmpty()?n.x:n.points.get(n.points.size()-1)[1];if((direction&10)!=0&&at>=time&&distance(at)<=approach){float yy=y(at),xx=x(pos,yy),len=half(yy)*2/chart.keys*.75f,sign=(direction&2)!=0?1:-1;p.setColor(0xffdbffa6);p.setStrokeWidth(4);c.drawLine(xx,yy,xx+sign*len,yy,p);c.drawLine(xx+sign*len,yy,xx+sign*(len-12),yy-10,p);c.drawLine(xx+sign*len,yy,xx+sign*(len-12),yy+10,p);}}
 c.restore();for(int lane=0;lane<chart.keys;lane++){float xx=x((lane+.5)*256/chart.keys,bottom);color(glow[lane]?0xff8cffff:0xff3f657a);c.drawRoundRect(xx-half(bottom)/chart.keys*.86f,bottom-4,xx+half(bottom)/chart.keys*.86f,bottom+9,4,4,p);if(glow[lane]){color(0x887affff);c.drawCircle(xx,bottom,22,p);}}
 text(c,"AUTO PREVIEW",getHeight()*.025f,getHeight()*.96f,0xffc3d9dd);if(combo>0){p.setShader(new LinearGradient(0,getHeight()*.29f,0,getHeight()*.44f,0xfffbb4e0,0xffb879ba,Shader.TileMode.CLAMP));text(c,Integer.toString(combo),getHeight()*.13f,getHeight()*.43f,0xffffffff);p.setShader(null);}if(hit){p.setShader(new LinearGradient(0,getHeight()*.17f,0,getHeight()*.29f,0xffffffff,0xff65d6aa,Shader.TileMode.CLAMP));text(c,"很棒",getHeight()*.085f,getHeight()*.275f,0xffffffff);p.setShader(null);}
 }
 void release(){if(background!=null){background.recycle();background=null;}for(Bitmap b:sprites.values())if(b!=null)b.recycle();sprites.clear();}
}
